function temaNoite(){try{return localStorage.getItem('vv_tema')==='noite'}catch(e){return false}}
function temaDraw(){const on=temaNoite();['temaC','temaP'].forEach(i=>{const e=$(i);if(e)e.innerHTML='<label class="tema"><span>🌙 Tema noite</span><input type="checkbox" class="sw"'+(on?' checked':'')+' onchange="temaSet(this.checked)"></label>'})}
function temaSet(on){try{localStorage.setItem('vv_tema',on?'noite':'claro')}catch(e){}document.documentElement.classList.toggle('dk',on);temaDraw()}
document.addEventListener('focusin',e=>{const t=e.target;if(t&&(t.tagName==='TEXTAREA'||(t.tagName==='INPUT'&&!/^(checkbox|radio|button|submit|file|range|color)$/.test(t.type)))&&matchMedia('(pointer:coarse)').matches)document.body.classList.add('kbd')});
document.addEventListener('focusout',()=>setTimeout(()=>{const a=document.activeElement;if(!a||!(a.tagName==='TEXTAREA'||a.tagName==='INPUT'))document.body.classList.remove('kbd')},150));
function uniEntrar(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));say('ctm','Entrando…');
 run('uniEntrar',d).then(async r=>{if(r.adm){try{await adm2fa()}catch(x){return say('ctm',esc(x.message),1)}S={email:String(d.tel).trim()};AD=await rpc('admin_listar');location.hash='#/admin';admAbrir();return}
  if(r.cli){CU=r.cli;ctaLocal();avisoSenha(1);cliBadge()}
  if(r.loja){await PNL();abrirLoja(r.loja,{whatsapp:d.tel});toast('Bem-vindo(a)!');location.hash='#/minha';return}
  ctaDraw();ctabDraw();pedCarregar();toast('Bem-vindo(a)!')}).catch(x=>say('ctm',esc(x.message),1));return false}
T.uniEntrar=async function(d){const [l,c]=await Promise.allSettled([T.login({whatsapp:d.tel,senha:d.senha}),T.contaEntrar({tel:d.tel,senha:d.senha})]);
 if(l.status==='fulfilled'&&l.value&&l.value.__admin)return{adm:1};
 const r={loja:l.status==='fulfilled'?l.value:null,cli:c.status==='fulfilled'?c.value:null};
 if(r.loja||r.cli)return r;
 const m=[l.reason,c.reason].map(x=>x&&x.message||'').find(x=>/conex|Muitas/i.test(x));throw new Error(m||'WhatsApp, e-mail ou senha incorretos.')};
function uniEsqueci(){const i=document.querySelector('#ctd input[name=tel]');recSenha('auto',i?i.value.trim():'')}

/* Cupons: simulador de quem paga e comissão (mesma conta do servidor) */
var CPTAB=null;

/* Campanhas (tags como 🔥FDV) */
function ctg(c,big){return '<span class="ctg'+(big?' big':'')+'" style="background:'+esc(/^#[0-9a-f]{6}$/i.test(c.cor)?c.cor:'#C0392B')+'">'+esc(c.tag)+'</span>'}
function campAtivas(){const m={};(D.produtos||[]).forEach(p=>{if(cpa(p)&&!m[p.camp.id])m[p.camp.id]=p.camp});return Object.values(m)}

/* ---------- Campanhas: administração ---------- */
T.adminCampanhas=()=>rpc('admin_campanhas');T.adminCampanhaSalvar=p=>rpc('admin_campanha_salvar',{p:p});T.adminCampanhaExcluir=id=>rpc('admin_campanha_excluir',{p_id:id});T.adminCampanhaItemRemover=(c,p)=>rpc('admin_campanha_item_remover',{p_camp:c,p_prod:p});
T.lojaCampanhas=()=>rpc('loja_campanhas');T.lojaCampanhaItem=(c,p,v,on)=>rpc('loja_campanha_item',{p_camp:c,p_prod:p,p_pct:v,p_on:on});
var CML=[],CME=null;

/* ---------- Campanhas: painel da loja ---------- */
var CMP=[];
var CMQ={};
T.lojaCampanhasVisto=ids=>rpc('loja_campanhas_visto',{p_ids:ids});
var TSTB='<div class="tstb">🧪 TESTE: só você está vendo · pedidos saem pelo preço normal</div>';
T.adminCampanhaLancar=(id,m)=>rpc('admin_campanha_lancar',{p_id:id,p_modo:m});
T.campContagem=()=>rpc('campanhas_contagem');T.prodParc=(id,n)=>rpc('loja_produto_parcelas',{p_id:id,p_n:n});T.lojaParcGeral=(n,r)=>rpc('loja_parcelas_geral',{p_n:n,p_reset:r});
function czwH(c,tab){const cor=/^#[0-9a-f]{6}$/i.test(c.cor)?c.cor:'#C0392B';return '<div class="czw" style="--cc:'+cor+'"'+(tab?'':' role="button" tabindex="0" onclick="czwIr(\''+esc(c.id)+'\')"')+'><div class="czl"><span class="czq"></span><span class="czx" data-ini="'+(+c.inicio||0)+'" data-fim="'+(+c.fim)+'"></span></div><div class="czn"><div><b>'+esc(c.nome)+'</b><span>'+esc(c.tag)+(c.pct?' · até '+(+c.pct)+'% OFF':'')+'</span></div>'+(tab?'':'<span class="cza">›</span>')+'</div></div>'+(c.teste?(c.n?TSTB:TSTP):'')}
var TSTP='<div class="tstb">🧪 Prévia: só você está vendo · a campanha ainda não foi lançada</div>';
function czwIr(id){if(campAtivas().some(c=>c.id===id))catIr('camp:'+id);else toast('Em breve: os produtos aparecem quando a campanha começar.')}
T.adminCampanhaPausar=(id,v)=>rpc('admin_campanha_pausar',{p_id:id,p_pausar:v});
